def predict(probe):
    # Rule 1: All 'R' characters are removed [E6, E8, E12]
    # Rule 2: The last character, if a letter, is incremented by 1 with wrap [E1-E5, E7, E9-E11]
    #         a->b ... z->a, A->B ... Z->A. Digits/symbols/spaces unchanged.
    # Order: remove R first, then increment last char of result [E6: carR->cas, Rword->wore]
    outputs = []
    for s in probe["inputs"]:
        t = s.replace("R", "")
        if t:
            c = t[-1]
            if 'a' <= c <= 'z':
                t = t[:-1] + chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
            elif 'A' <= c <= 'Z':
                t = t[:-1] + chr((ord(c) - ord('A') + 1) % 26 + ord('A'))
        outputs.append(t)
    return {"outputs": outputs}
